package com.Xiaoniu2333.mlky.machinecode.common;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Objects;
import java.util.UUID;

/**
 * The wire format shared by the client mod, Velocity bridge and Paper backend.
 *
 * <p>Channel: {@value #CHANNEL}. A client payload is forwarded by Velocity with a 16-byte player
 * UUID prefix. The prefix is generated by the proxy, never by the client, so a backend cannot be
 * tricked into attributing a report to another player by a payload field.</p>
 *
 * <pre>
 * client -&gt; proxy:
 *   byte    protocol version (1)
 *   utf     hashed machine code (64 lower-case hex)
 *   utf     platform (WINDOWS/LINUX/MACOS)
 *   utf     os name
 *   utf     os version
 *   utf     architecture
 *   utf     mod version
 *
 * proxy -&gt; backend:
 *   long    player UUID most significant bits
 *   long    player UUID least significant bits
 *   ...     the unchanged client payload
 * </pre>
 */
public final class Protocol {
    public static final String CHANNEL = "machinecode:main";
    public static final int VERSION = 1;
    public static final int MAX_PAYLOAD_BYTES = 4096;
    public static final int MAX_FIELD_LENGTH = 128;

    private Protocol() {
    }

    /**
     * A report built on the client.
     */
    public record ClientReport(
            String machineCode,
            Platform platform,
            String osName,
            String osVersion,
            String architecture,
            String modVersion
    ) {
        public ClientReport {
            if (!MachineCodeValidator.isMachineCode(machineCode)) {
                throw new IllegalArgumentException("machineCode must be 64 lower-case hex characters");
            }
            Objects.requireNonNull(platform, "platform");
            osName = cleanField(osName, "unknown");
            osVersion = cleanField(osVersion, "unknown");
            architecture = cleanField(architecture, "unknown");
            modVersion = cleanField(modVersion, "unknown");
        }

        public static ClientReport from(final HardwareFingerprint.CapturedFingerprint captured,
                                        final String modVersion) {
            return new ClientReport(
                    captured.machineCode(),
                    captured.platform(),
                    captured.osName(),
                    captured.osVersion(),
                    captured.architecture(),
                    modVersion
            );
        }

        public byte[] encode() {
            try {
                final ByteArrayOutputStream bytes = new ByteArrayOutputStream(256);
                try (DataOutputStream output = new DataOutputStream(bytes)) {
                    output.writeByte(VERSION);
                    output.writeUTF(machineCode);
                    output.writeUTF(platform.wireName());
                    output.writeUTF(osName);
                    output.writeUTF(osVersion);
                    output.writeUTF(architecture);
                    output.writeUTF(modVersion);
                }
                final byte[] result = bytes.toByteArray();
                if (result.length > MAX_PAYLOAD_BYTES) {
                    throw new IllegalStateException("MachineCode payload is too large");
                }
                return result;
            } catch (final IOException exception) {
                throw new IllegalStateException("Unable to encode MachineCode payload", exception);
            }
        }
    }

    /**
     * A report after Velocity prepended the authenticated proxy-side player UUID.
     */
    public record ForwardedReport(UUID playerId, ClientReport report) {
    }

    public static byte[] encode(final ClientReport report) {
        return report.encode();
    }

    public static ClientReport decodeClientReport(final byte[] payload) {
        Objects.requireNonNull(payload, "payload");
        if (payload.length == 0 || payload.length > MAX_PAYLOAD_BYTES) {
            throw new ProtocolException("Invalid MachineCode payload length");
        }
        try (DataInputStream input = new DataInputStream(new ByteArrayInputStream(payload))) {
            final int version = input.readUnsignedByte();
            if (version != VERSION) {
                throw new ProtocolException("Unsupported MachineCode protocol version: " + version);
            }
            final String machineCode = readField(input);
            if (!MachineCodeValidator.isMachineCode(machineCode)) {
                throw new ProtocolException("Invalid machine code in payload");
            }
            final String platformName = readField(input);
            final Platform platform = Platform.fromWireName(platformName)
                    .orElseThrow(() -> new ProtocolException("Unknown platform in payload"));
            final String osName = readField(input);
            final String osVersion = readField(input);
            final String architecture = readField(input);
            final String modVersion = readField(input);
            if (input.available() != 0) {
                throw new ProtocolException("Unexpected trailing bytes in MachineCode payload");
            }
            return new ClientReport(
                    machineCode, platform, osName, osVersion, architecture, modVersion);
        } catch (final EOFException exception) {
            throw new ProtocolException("Truncated MachineCode payload", exception);
        } catch (final IOException exception) {
            throw new ProtocolException("Malformed MachineCode payload", exception);
        }
    }

    public static byte[] frameForBackend(final UUID playerId, final byte[] clientPayload) {
        Objects.requireNonNull(playerId, "playerId");
        Objects.requireNonNull(clientPayload, "clientPayload");
        if (clientPayload.length == 0 || clientPayload.length > MAX_PAYLOAD_BYTES) {
            throw new ProtocolException("Invalid client payload length");
        }
        return ByteBuffer.allocate(16 + clientPayload.length)
                .putLong(playerId.getMostSignificantBits())
                .putLong(playerId.getLeastSignificantBits())
                .put(clientPayload)
                .array();
    }

    public static ForwardedReport decodeForwarded(final byte[] data) {
        Objects.requireNonNull(data, "data");
        if (data.length < 17 || data.length > 16 + MAX_PAYLOAD_BYTES) {
            throw new ProtocolException("Invalid forwarded MachineCode payload length");
        }
        final ByteBuffer header = ByteBuffer.wrap(data, 0, 16);
        final UUID playerId = new UUID(header.getLong(), header.getLong());
        final byte[] payload = new byte[data.length - 16];
        System.arraycopy(data, 16, payload, 0, payload.length);
        return new ForwardedReport(playerId, decodeClientReport(payload));
    }

    private static String readField(final DataInputStream input) throws IOException {
        final String value = input.readUTF();
        if (value.length() > MAX_FIELD_LENGTH || value.indexOf('\0') >= 0) {
            throw new ProtocolException("Invalid field in MachineCode payload");
        }
        return value;
    }

    private static String cleanField(final String value, final String fallback) {
        if (value == null) {
            return fallback;
        }
        final String cleaned = value.replace('\0', ' ')
                .replaceAll("[\\p{Cntrl}]", " ")
                .trim()
                .replaceAll("\\s+", " ");
        if (cleaned.isEmpty()) {
            return fallback;
        }
        return cleaned.length() <= MAX_FIELD_LENGTH
                ? cleaned
                : cleaned.substring(0, MAX_FIELD_LENGTH);
    }

    /**
     * Checked protocol error. The message is safe for logs.
     */
    public static final class ProtocolException extends IllegalArgumentException {
        public ProtocolException(final String message) {
            super(message);
        }

        public ProtocolException(final String message, final Throwable cause) {
            super(message, cause);
        }
    }

    /**
     * Utility for support tools: renders bytes as UTF-8 without throwing.
     */
    public static String printable(final byte[] data) {
        return new String(data, StandardCharsets.UTF_8);
    }
}
